public bool IsEffectUnlocked(SpecialEffectType type)
	{
		if (EffectUnlocked == null)
		{
			EffectUnlocked = new Dictionary<SpecialEffectType, bool>();
		}
		return EffectUnlocked.ContainsKey(type) && EffectUnlocked[type];
	}

public void UnlockEffect(SpecialEffectType type)
	{
		if (!IsEffectUnlocked(type))
		{
			if (EffectUnlocked.ContainsKey(type))
			{
				EffectUnlocked[type] = true;
			}
			else
			{
				EffectUnlocked.Add(type, value: true);
			}
		}
	}

