	{
		if (!AdditionalData.ContainsInt(key))
		{
			AdditionalData.AddOrUpdateData(key, UnityEngine.Random.Range(0, int.MaxValue));
		}
		UnityEngine.Random.InitState(AdditionalData.GetInt(key));
		run();
		UnityEngine.Random.InitState(AdditionalData.GetInt(key));
