public void RemoveTownEffect(TownEffectBase effect)
	{
		TownEffectBase townEffectBase = GetTownEffects().FirstOrDefault((TownEffectBase e) => e == effect);
		if (townEffectBase != null)
		{
			GetTownEffects().Remove(townEffectBase);
			ReceiveEvent(GameWorldEvent.TownEffectRemoved, townEffectBase);
		}
	}

public void AddTownEffect(TownEffectBase effect, object trigger)
	{
		if (GetTownEffects().Any((TownEffectBase ef) => ef.CanbeMergedWith(effect)))
		{
			TownEffectBase townEffectBase = GetTownEffects().First((TownEffectBase ef) => ef.CanbeMergedWith(effect));
			townEffectBase.Merge(effect);
		}
		else
		{
			GetTownEffects().Add(effect);
			ReceiveEvent(GameWorldEvent.TownEffectAdded, new TownEffectAddedEvent
			{
				Effect = effect,
				Trigger = trigger
			});
		}
		ReceiveEvent(GameWorldEvent.TownEffectGenerated, new TownEffectAddedEvent
		{
			Effect = effect,
			Trigger = trigger
		});
	}

