public void ClearUpData()
	{
		Items = Items.Where((Item i) => i != null).ToList();
		SaveFileName = SaveFileName.Replace(".sav", ".dragon");
		if (CurrentJourneys == null)
		{
			CurrentJourneys = new List<TripRecord>();
		}
		if (CurrentVehicles == null)
		{
			CurrentVehicles = new List<Vehicle>();
		}
		CurrentJourneys.RemoveAll((TripRecord j) => j.Claimed && j.Completed);
		if (!StarRating.HasValue)
		{
			StarRating = 1;
		}
		if (TownEffects != null)
		{
			IEnumerable<ArmoryMasteryEffect> toremove = from e in TownEffects.OfType<ArmoryMasteryEffect>()
				where e.NumberOfTriggersLeft > 2000
				select e;
			TownEffects.RemoveAll((TownEffectBase t) => toremove.Any((ArmoryMasteryEffect a) => a == t));
		}
		if (Progresses == null || !Progresses.Any())
		{
			Progresses = new Dictionary<int, PlayerProgress>
			{
				{
					1,
					new PlayerProgress
					{
						QuestCompletionRecords = QuestCompletionRecords,
						QuestChainCompletionRecords = QuestChainCompletionRecords,
						Reputation = Reputation,
						Quests = Quests,
						DungeonRecords = DungeonRecords,
						QuestIssuedRecords = QuestIssuedRecords,
						DialogSpokenRecords = DialogSpokenRecords,
						StoryTriggerDates = StoryTriggerDates,
						StoryTriggeredRecords = StoryTriggeredRecords,
						MaxAchievedDifficultyValue = Reputation / 100.0
					}
				},
				{
					2,
					PlayerProgress.Init()
				},
				{
					3,
					PlayerProgress.Init()
				},
				{
					4,
					PlayerProgress.Init()
				},
				{
					5,
					PlayerProgress.Init()
				},
				{
					6,
					PlayerProgress.Init()
				},
				{
					7,
					PlayerProgress.Init()
				},
				{
					8,
					PlayerProgress.Init()
				},
				{
					9,
					PlayerProgress.Init()
				},
				{
					10,
					PlayerProgress.Init()
				}
			};
		}
		for (int num = 1; num <= 10; num++)
		{
			if (!Progresses.ContainsKey(num))
			{
				Progresses.Add(num, PlayerProgress.Init());
			}
		}
		foreach (KeyValuePair<int, PlayerProgress> progress in Progresses)
		{
			if (progress.Value != null)
			{
				if (progress.Value.DungeonRecords.All((DungeonRecord d) => d.AdventureType != AdventureType.NorthernTerritory))
				{
					progress.Value.DungeonRecords.Add(DungeonRecord.InitLockedRecord(AdventureType.NorthernTerritory));
				}
				progress.Value.Quests.RemoveAll((Quest q) => q == null);
			}
		}
		foreach (Resident resident in Residents)
		{
			if (resident.JourneyContributionModifiers == null)
			{
				resident.JourneyContributionModifiers = resident.Type.GetResidentBase().GenerateJourneyContributions(GetDifficultyLevelMeasurement_OneStar(), resident.Grade);
			}
		}
		if (Candidates != null)
		{
			foreach (ResidentCandidate candidate in Candidates)
			{
				if (candidate.Candidate.JourneyContributionModifiers == null)
				{
					candidate.Candidate.JourneyContributionModifiers = candidate.Candidate.Type.GetResidentBase().GenerateJourneyContributions(GetDifficultyLevelMeasurement_OneStar(), candidate.Candidate.Grade);
				}
			}
		}
		if (Resources != null)
		{
			ResourcesAt = ((ResourcesAt != null && ResourcesAt.Any()) ? ResourcesAt : new Dictionary<ResourceType, ResourceProfileAntiCheat>());
			foreach (ResourceProfile resource in Resources)
			{
				if (ResourcesAt.ContainsKey(resource.ResourceType))
				{
					ResourcesAt[resource.ResourceType] = new ResourceProfileAntiCheat
					{
						ResourceType = resource.ResourceType,
						Amount = resource.Amount * CurrentKey
					};
				}
				else
				{
					ResourcesAt.Add(resource.ResourceType, new ResourceProfileAntiCheat
					{
						ResourceType = resource.ResourceType,
						Amount = resource.Amount * CurrentKey
					});
				}
			}
		}
		if (!AchievedDifficultyValue.HasValue)
		{
			AchievedDifficultyValue = GetProgress().Reputation / 100.0;
		}
		double? achievedDifficultyValue = AchievedDifficultyValue;
		if (achievedDifficultyValue.HasValue && achievedDifficultyValue.GetValueOrDefault() < GetProgress().Reputation / 100.0)
		{
			AchievedDifficultyValue = GetProgress().Reputation / 100.0;
		}
		foreach (AdventurerProfile adventurerProfile in AdventurerProfiles)
		{
			if (!(adventurerProfile.TalentVersionDetails != TalentVersionDetails))
			{
				continue;
			}
			if (adventurerProfile.Talents == null)
			{
				adventurerProfile.Talents = new List<IAdventurerTalent>();
			}
			foreach (IAdventurerTalent talent in adventurerProfile.Talents)
			{
				talent.Reset(adventurerProfile);
			}
			adventurerProfile.Talents = (adventurerProfile.UnitClass.GetConfiguration() as AdventurerUnitConfigurationBase).GenerateTalents();
			adventurerProfile.TalentPoints = adventurerProfile.GetLevel() / 5;
			if (adventurerProfile.TalentPoints > 17)
			{
				adventurerProfile.TalentPoints = 17;
			}
			adventurerProfile.TalentVersionDetails = TalentVersionDetails;
		}
		if (NumberOfResidentSlots > MaxResidentSlot)
		{
			NumberOfResidentSlots = MaxResidentSlot;
			Residents = ((Residents == null) ? new List<Resident>() : Residents.Take(MaxResidentSlot).ToList());
		}
		if ((from b in Buildings
			select b.Value into b
			where b != null && b is RecruitmentFacility
			select b).FirstOrDefault() is RecruitmentFacility recruitmentFacility)
		{
			foreach (AdventurerCandidate candidate2 in recruitmentFacility.Candidates)
			{
				AdventurerProfile profile = candidate2.Profile;
				if (profile.Talents == null)
				{
					profile.Talents = new List<IAdventurerTalent>();
				}
				if (!(profile.TalentVersionDetails != TalentVersionDetails))
				{
					continue;
				}
				foreach (IAdventurerTalent talent2 in profile.Talents)
				{
					talent2.Reset(profile);
				}
				profile.Talents = (profile.UnitClass.GetConfiguration() as AdventurerUnitConfigurationBase).GenerateTalents();
				profile.TalentPoints = profile.GetLevel() / 5;
				if (profile.TalentPoints > 17)
				{
					profile.TalentPoints = 17;
				}
				profile.TalentVersionDetails = TalentVersionDetails;
			}
		}
		if (TownEffects != null)
		{
			TownEffects = TownEffects.Where((TownEffectBase ef) => ef != null).ToList();
		}
		if (EndlessRecord == null)
		{
			EndlessRecord = DungeonRecord.InitLockedRecord(AdventureType.Endless_Entry);
		}
		if (!AdditionalData.ContainsString(Adventure.EndlessAdventureLevelKey))
		{
			AdditionalData.AddOrUpdateData(Adventure.EndlessAdventureLevelKey, Adventure.EndlessAdventurePartial + EndlessDungeonDifficultyValue.GetValueOrDefault());
		}
	}

