		{
			exceededValue = num2 - num3;
			num2 = num3;
		}
		TownBoostValue townBoostValue = new TownBoostValue();
		townBoostValue.FinalValue = num * num2;
		townBoostValue.ExceededValue = exceededValue;
		return townBoostValue;
	}

private void ChangeResource(ResourceType type, double change, List<Item> relatedItems)
	{
		if (relatedItems.Any((Item i) => i == null))
		{
			SteamExceptionHandle.Handle(new Exception("Null item!! " + type));
			return;
		}
		ResourceCategory resourceCategory = type.GetResourceCategory();
		bool flag = resourceCategory == ResourceCategory.ProductionRecipe && !HasResource(type);
		bool flag2 = resourceCategory == ResourceCategory.AdventurerInvitation && !HasResource(type);
		bool flag3 = resourceCategory == ResourceCategory.BuildingPermit && !HasResource(type);
		bool flag4 = resourceCategory == ResourceCategory.SkillBooks && !HasResource(type);
		if (resourceCategory.IsUniqueResource() && change > 0.0)
		{
			if (ResourcesAt.ContainsKey(type))
			{
				ResourcesAt[type].Amount = 1.0 * CurrentKey;
			}
			else
			{
				ResourcesAt.Add(type, new ResourceProfileAntiCheat
				{
					ResourceType = type,
					Amount = 1.0 * CurrentKey
				});
			}
		}
		else if ((type.IsItem() && GetResourceQuantity(type) < MaxPossibleResources_Item) || (!type.IsItem() && GetResourceQuantity(type) < MaxPossibleResources_NonItem) || change < 0.0)
		{
			if (ResourcesAt.ContainsKey(type))
			{
				ResourcesAt[type].ChangeValue(change);
				if ((double)ResourcesAt[type].GetValue() < 0.0)
				{
					ResourcesAt[type].SetValue(0.0);
				}
			}
			else
			{
				ResourcesAt.Add(type, new ResourceProfileAntiCheat
				{
					ResourceType = type,
					Amount = change * CurrentKey
				});
			}
			if (relatedItems.Count > 0)
			{
				if (change >= 0.0)
				{
					relatedItems.ForEach(delegate(Item i)
					{
						i.ItemStatus = ItemStatus.Reserved;
					});
					Items.AddRange(relatedItems);
				}
				else
				{
					relatedItems.ForEach(delegate(Item i)
					{
						i.ItemStatus = ItemStatus.Removed;
					});
					Items.RemoveAll((Item i) => i.ItemStatus == ItemStatus.Removed);
				}
			}
		}
		ReceiveEvent(GameWorldEvent.ResourceUpdated, new ResourceUpdateEvent
		{
			ResourceType = type,
			RelatedItems = relatedItems,
			Change = change,
			ResultedAmount = ResourcesAt[type].GetValue(),
			OriginalAmount = (double)ResourcesAt[type].GetValue() - change
		});
		if (flag4)
		{
			SkillType skill = SkillExtensions.SkillBookDictionary[type];
			if (AcquiredPassives.All((SkillType s) => s != skill))
			{
				AcquiredPassives.Add(skill);
			}
			ReceiveEvent(GameWorldEvent.NewSkillUnlocked, skill);
		}
		if (flag)
		{
			ResourceType productType = BuildingExtensions.Recipes.First((Recipe r) => r.RecipeName == type).ProductType;
