public List<Item> GetProductionResourceItems(int amount, ResourceType type)
	{
		if (!type.IsItem())
		{
			throw new Exception("Invalid resource");
		}
		if (Items.Count((Item i) => i.Type == type && i.ItemStatus == ItemStatus.StockForProduction) < amount)
		{
			throw new Exception("Insufficient amount of items.");
		}
		return Items.Where((Item i) => i.Type == type && i.ItemStatus == ItemStatus.StockForProduction).Take(amount).ToList();
	}

public void BatchResourceUpdate(List<ResourceUpdate> changes)
	{
		List<ResourceUpdate> list = (from c in changes
			group c by c.ResourceType into g
			select new ResourceUpdate
			{
				ResourceType = g.Key,
				ChangeAmount = g.Sum((ResourceUpdate r) => r.ChangeAmount),
				RelatedItems = g.SelectMany((ResourceUpdate r) => r.RelatedItems).ToList()
			}).ToList();
		foreach (ResourceUpdate item in list)
		{
			ChangeResource(item.ResourceType, item.ChangeAmount, item.RelatedItems);
		}
		if (IsInventoryFull())
		{
			ReceiveEvent(GameWorldEvent.InventoryIsFull, null);
		}
	}

