public void CompleteQuest(Quest quest)
	{
		if (quest.Rewarded)
		{
			return;
		}
		quest.Rewarded = true;
		GetProgress().Quests.Remove(quest);
		foreach (QuestRewardBase reward in quest.Rewards)
		{
			reward.Reward(quest);
		}
		QuestCompletedEvent questCompletedEvent = new QuestCompletedEvent();
		questCompletedEvent.Quest = quest;
		questCompletedEvent.AdditionalContribution = new List<ResourceUpdate>();
		QuestCompletedEvent questCompletedEvent2 = questCompletedEvent;
		if (GetProgress().QuestCompletionRecords == null)
		{
			GetProgress().QuestCompletionRecords = new Dictionary<QuestIdentifier, int>();
		}
		if (GetProgress().QuestCompletionRecords.ContainsKey(quest.QuestIdentifier))
		{
			GetProgress().QuestCompletionRecords[quest.QuestIdentifier]++;
		}
		else
		{
			GetProgress().QuestCompletionRecords.Add(quest.QuestIdentifier, 1);
		}
		string key = quest.QuestIdentifier.ToString() + "-" + GetStarRating() + "-CompletionDate";
		if (!AdditionalData.ContainsInt(key))
		{
			AdditionalData.AddOrUpdateData(quest.QuestIdentifier.ToString() + "-" + GetStarRating() + "-FirstCompletionDate", GameDays);
		}
		GameWorld.instance.PlayerProfile.ReceiveEvent(GameWorldEvent.QuestCompleted, questCompletedEvent2);
		if (questCompletedEvent2.AdditionalContribution.Any())
		{
			GameWorld.instance.PlayerProfile.ReceiveEvent(GameWorldEvent.ResidentContributed, new ResidentResourceContributeEvent
			{
				Contributor = null,
				ResourceUpdates = questCompletedEvent2.AdditionalContribution
			});
		}
		BatchResourceUpdate(questCompletedEvent2.AdditionalContribution);
	}

