public void ReleaseAdventurer(AdventurerProfile profile)
	{
		if (AdventurerProfiles.Count <= 1)
		{
			return;
		}
		AdventurerProfile adventurerProfile = AdventurerProfiles.FirstOrDefault((AdventurerProfile p) => p.Id == profile.Id);
		if (adventurerProfile == null)
		{
			return;
		}
		List<Item> equipments = adventurerProfile.GetEquipments();
		foreach (Item item in equipments.ToList())
		{
			adventurerProfile.Disrobe(item, needsRecache: false);
		}
		AdventurerProfiles.Remove(adventurerProfile);
		double changeAmount = (double)adventurerProfile.Experience * ReleaseAdventurerGainPointsRatio;
		List<ResourceUpdate> list = new List<ResourceUpdate>();
		list.Add(new ResourceUpdate
		{
			ResourceType = ResourceType.PracticePoints,
			ChangeAmount = changeAmount,
			RelatedItems = new List<Item>()
		});
		List<ResourceUpdate> list2 = list;
		BatchResourceUpdate(list2);
		ReceiveEvent(GameWorldEvent.AdventurerListUpdated, new AdventurerListUpdatedEvent
		{
			AdventurerListUpdateType = AdventurerListUpdateType.Release,
			ChangedProfiles = new List<AdventurerProfile> { adventurerProfile },
			RelatedResourceUpdates = list2.Select((ResourceUpdate u) => new ResourceUpdate
			{
				ResourceType = u.ResourceType,
				ChangeAmount = u.ChangeAmount,
				RelatedItems = u.RelatedItems
			}).ToList()
		});
	}

public void Save()
	{
		string text = SystemProcessor.ApplicationPath + SaveFileName;
		string text2 = SystemProcessor.ApplicationPath + SaveFileName + "temp";
		if (File.Exists(text2))
		{
			File.Delete(text2);
		}
		BinaryFormatter binaryFormatter = new BinaryFormatter();
		FileStream fileStream = File.Create(text2);
		Resources = new List<ResourceProfile>();
		foreach (KeyValuePair<ResourceType, ResourceProfileAntiCheat> item in ResourcesAt)
		{
			Resources.Add(new ResourceProfile
			{
				ResourceType = item.Key,
				Amount = (double)item.Value.Amount / CurrentKey
			});
		}
		binaryFormatter.Serialize(fileStream, this);
		fileStream.Close();
		if (File.Exists(text))
		{
			File.Delete(text);
		}
		File.Move(text2, text);
	}

