		if (determinedQualityCoef > 0.6 && determinedQualityCoef <= 0.8)
		{
			grade = QualityGrade.Legendary;
		}
		if (determinedQualityCoef > 0.8)
		{
			grade = QualityGrade.Ancient;
		}
		Resident resident = new Resident();
		resident.Type = type;
		resident.Level = difficultyLevelMeasurement.GetResidentLevel();
		resident.Grade = grade;
		resident.Id = Guid.NewGuid().ToString();
		resident.UntilLevelUpDaysCounter = ResidentLevelUpRequiredDays(2);
		resident.Effects = type.GetResidentBase().GetEffects(difficultyLevelMeasurement, determinedQualityCoef + 1.0);
		resident.GeneratedOnDifficultyValue = difficultyLevelMeasurement.DifficultyValue;
		resident.GeneratedOnStarRating = difficultyLevelMeasurement.StarRating;
