public void AddProcessDays(int numberOfDays)
	{
		if (DayCounter == null)
		{
			DayCounter = string.Empty;
			for (int i = 0; i < CurrentAtDays; i++)
			{
				DayCounter += "-";
			}
		}
		if (CurrentAtDays != DayCounter.Length)
		{
			CurrentAtDays = 0;
			DayCounter = string.Empty;
			Application.Quit();
		}
		CurrentAtDays += numberOfDays;
		for (int j = 0; j < numberOfDays; j++)
		{
			DayCounter += "-";
		}
		if (CurrentAtDays >= DaysRequired)
		{
			CurrentAtDays = 0;
			DayCounter = string.Empty;
