			resourceConsumptionPerDay.Consume();
			AddProcessDays(1);
			{
				foreach (Resident resident in GameWorld.instance.PlayerProfile.Residents)
				{
					int num = UnityEngine.Random.Range(ActivePointsFrom, ActivePointsToExclusive);
					if (resident.AddHappiness(num, Type))
