protected void GenerateOrientedAdventurers(List<UnitClassStyle> styles)
	{
		List<RecruitmentCandidatePresence> allAdventurerPresences = GetAllAdventurerPresences();
		List<RecruitmentCandidatePresence> list = allAdventurerPresences.Where((RecruitmentCandidatePresence p) => styles.Any((UnitClassStyle st) => p.UnitClass.GetConfiguration().CorrespondingClassStyle == st)).ToList();
		RecruitmentCandidatePresence recruitmentCandidatePresence = allAdventurerPresences.WeightedRandomSelect();
		if (list.Any())
		{
			recruitmentCandidatePresence = list.WeightedRandomSelect();
		}
		double boostRate = GetEventResultValue(0.1, 0.8) + GameWorld.instance.PlayerProfile.GetAdventurerSpawnBoost();
		foreach (RecruitmentQualityBoostEffect item in GameWorld.instance.PlayerProfile.GetTownEffects().OfType<RecruitmentQualityBoostEffect>().ToList())
		{
			item.RemoveTrigger(1);
		}
		QualityGrade grade = ItemExtensions.DefaultAdventurerSpawnDistribution().BoostDrop(boostRate).GetGrade();
		float quality = UnitExtensions.GenerateGradeQualitySettingValueForAdventurer(grade, (!GameWorld.instance.PlayerProfile.GetEnabledStars().Any((int s) => s == 2)) ? 0.0 : 0.6);
		AdventurerProfile profile = recruitmentCandidatePresence.UnitClass.GenerateAdventurerProfileWithDefinedQuality(quality);
		List<AdventurerCandidate> list2 = new List<AdventurerCandidate>();
		list2.Add(new AdventurerCandidate
		{
			Profile = profile,
			DaysTillExpiration = RecruitmentFacility.AdventurerCandidateExpiration
		});
		List<AdventurerCandidate> candidates = list2;
		if ((from b in GameWorld.instance.PlayerProfile.Buildings
			select b.Value into b
			where b != null && b.BuildingType == BuildingType.RecruitmentFacility
			select b).FirstOrDefault() is RecruitmentFacility recruitmentFacility)
		{
			recruitmentFacility.AddCandidates(candidates);
		}
	}

